"""Write the canonical LUT manifest as JSON and generated CommonJS."""
from __future__ import annotations

import json
from pathlib import Path


def javascript_manifest(manifest: list[dict]) -> str:
    """Render the generated module loaded by the Mini Program."""
    payload = json.dumps(manifest, indent=2, ensure_ascii=False, allow_nan=False)
    return (
        "// Generated by tools/convert_luts.py; do not edit.\n"
        f"module.exports = {payload};\n"
    )


def write_manifest(output_dir: Path, manifest: list[dict]) -> None:
    """Keep the harness JSON and Mini Program JS byte-for-byte reproducible."""
    payload = json.dumps(manifest, indent=2, ensure_ascii=False, allow_nan=False) + "\n"
    (output_dir / "luts.json").write_text(payload, encoding="utf-8")
    (output_dir / "luts.js").write_text(javascript_manifest(manifest), encoding="utf-8")
    parsed = json.loads(payload)
    if parsed != manifest:
        raise ValueError("LUT manifest failed JSON round-trip verification")
